var i=`0491-shakriyeh`;var t=`world-0491`;var a=`SY`;var o=`western-asia`;var r=4;var s=112;var l={en:`Shakriyeh`,ua:`Шакріє`};var g={en:`A traditional dish from Syria, centered on lamb, yellow onion, bay leaf, plain yogurt. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: ягнятина, жовта цибуля, лавровий лист, натуральний йогурт. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,680,`g`],[`yellow-onion`,160,`g`],[`unsalted-butter`,45,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 75 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 75 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:75,i:[[`water`,520,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`plain-yogurt`,650,`g`],[`cornstarch`,25,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`garlic`,3,`clove`],[`cilantro`,35,`g`]]}];var u={slug:i,id:t,country:`SY`,region:o,servings:4,minutes:112,title:l,text:g,steps:d};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,i as slug,d as steps,g as text,l as title};